/**
 * Night Garden FLEET-69b5ee9aba
 * Event Website JavaScript
 * No external dependencies, no localStorage usage
 */

(function() {
  'use strict';

  // DOM Elements
  const showSoldOutBtn = document.getElementById('showSoldOutBtn');
  const soldOutCard = document.getElementById('midnight-concert');

  /**
   * Show the sold-out midnight concert card
   * @returns {void}
   */
  function showSoldOut() {
    if (soldOutCard) {
      soldOutCard.classList.add('visible');
      soldOutCard.setAttribute('aria-hidden', 'false');
      soldOutCard.setAttribute('tabindex', '0');
    }
  }

  /**
   * Event handler for the "Show sold out" button
   * @param {Event} event - The click event
   * @returns {void}
   */
  function handleShowSoldOutClick(event) {
    event.preventDefault();
    showSoldOut();

    // Update button state
    if (showSoldOutBtn) {
      showSoldOutBtn.textContent = 'Sold out revealed';
      showSoldOutBtn.disabled = true;
      showSoldOutBtn.setAttribute('aria-pressed', 'true');
    }
  }

  /**
   * Initialize event listeners and state
   * @returns {void}
   */
  function init() {
    // Add click event listener to the button
    if (showSoldOutBtn) {
      showSoldOutBtn.addEventListener('click', handleShowSoldOutClick);

      // Set initial ARIA state
      showSoldOutBtn.setAttribute('aria-pressed', 'false');
      showSoldOutBtn.setAttribute('type', 'button');
    }

    // Set initial ARIA state for the sold-out card
    if (soldOutCard) {
      soldOutCard.setAttribute('aria-hidden', 'true');
    }
  }

  // Initialize when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

  // Expose showSoldOut function globally for testing
  window.showSoldOut = showSoldOut;
})();

