/* Reset and Base Styles */
*, *::before, *::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  line-height: 1.6;
  color: #1a1a2e;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
}

/* Site Header */
.site-header {
  background: rgba(255, 255, 255, 0.95);
  padding: 1.5rem 1rem;
  text-align: center;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
}

.site-header h1 {
  margin: 0;
  font-size: 2rem;
  font-weight: 800;
  color: #1a1a2e;
  letter-spacing: -0.02em;
}

/* Event Container */
.event-container {
  padding: 1rem;
  max-width: 1200px;
  margin: 0 auto;
}

/* Event Grid */
.event-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.5rem;
  margin-bottom: 2rem;
}

/* Event Cards */
.event-card {
  background: #fff;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  position: relative;
}

.event-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 15px 35px rgba(0, 0, 0, 0.2);
}

.event-card.sold-out {
  opacity: 0;
  transform: scale(0.9);
  transition: opacity 0.5s ease, transform 0.5s ease;
  display: none;
}

.event-card.sold-out.visible {
  display: block;
  opacity: 1;
  transform: scale(1);
}

/* Event Badges */
.event-badge {
  position: absolute;
  top: 1rem;
  right: 1rem;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  padding: 0.375rem 0.75rem;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.event-badge--soldout {
  background: linear-gradient(135deg, #ff4757 0%, #ff6b81 100%);
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0%, 100% {
    box-shadow: 0 0 0 0 rgba(255, 71, 87, 0.7);
  }
  50% {
    box-shadow: 0 0 0 8px rgba(255, 71, 87, 0);
  }
}

/* Event Title */
.event-title {
  padding: 1.5rem 1.5rem 0.5rem;
  margin: 0;
  font-size: 1.5rem;
  font-weight: 700;
  color: #1a1a2e;
}

/* Event Meta */
.event-time,
.event-location {
  padding: 0 1.5rem;
  font-size: 0.875rem;
  color: #666;
  margin: 0.25rem 0;
}

.event-location {
  font-weight: 500;
  color: #4a4a6a;
}

/* Event Description */
.event-description {
  padding: 0 1.5rem 1rem;
  font-size: 0.9rem;
  color: #555;
  line-height: 1.6;
  margin: 0;
}

/* Event Link */
.event-link {
  display: block;
  padding: 0.75rem 1.5rem;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  text-decoration: none;
  font-weight: 600;
  border-radius: 0 0 16px 16px;
  transition: background 0.3s ease, transform 0.2s ease;
}

.event-link:hover {
  background: linear-gradient(135deg, #5a6fd6 0%, #6a3f94 100%);
  transform: translateY(-2px);
}

/* Event Status (Sold Out) */
.event-status {
  text-align: center;
  padding: 0.75rem;
  background: #ff4757;
  color: white;
  font-weight: 700;
  border-radius: 0 0 16px 16px;
}

/* Site Footer */
.site-footer {
  text-align: center;
  padding: 2rem 1rem;
  background: rgba(255, 255, 255, 0.95);
}

/* Show Sold Out Button */
.show-soldout-btn {
  background: linear-gradient(135deg, #2ecc71 0%, #27ae60 100%);
  color: white;
  border: none;
  padding: 0.875rem 2rem;
  font-size: 1rem;
  font-weight: 700;
  border-radius: 50px;
  cursor: pointer;
  box-shadow: 0 4px 15px rgba(46, 204, 113, 0.4);
  transition: all 0.3s ease;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.show-soldout-btn:hover {
  transform: translateY(-3px);
  box-shadow: 0 6px 20px rgba(46, 204, 113, 0.5);
}

.show-soldout-btn:active {
  transform: translateY(-1px);
}

/* Mobile Responsiveness */
@media (max-width: 375px) {
  .site-header h1 {
    font-size: 1.5rem;
  }

  .event-title {
    font-size: 1.25rem;
  }

  .event-description {
    font-size: 0.85rem;
  }

  .show-soldout-btn {
    padding: 0.75rem 1.5rem;
    font-size: 0.875rem;
  }
}

/* High Contrast Mode Support */
@media (prefers-contrast: high) {
  .event-card {
    border: 2px solid #1a1a2e;
  }

  .show-soldout-btn {
    border: 2px solid currentColor;
  }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  .event-card,
  .show-soldout-btn {
    transition: none;
  }
}

/* Print Styles */
@media print {
  .site-header,
  .site-footer {
    background: none;
  }

  .show-soldout-btn {
    display: none;
  }

  .event-card.sold-out {
    display: block !important;
  }
}
